/// <summary>
/// AVA
/// </summary>
[DataContractAttribute]
[SysOperationAlwaysInitializeAttribute]
class AVALedgerAllocBasisRuleExportContract implements SysOperationInitializable, SysOperationValidatable
{
    private AVAArchiveId    archiveId;
    private AVAArchiveDate  archiveDate;

}

Method.Source:
[DataMemberattribute]
public AVAArchiveId parmArchiveId(AVAArchiveId _archiveId = archiveId)
{
    archiveId = _archiveId;
    return archiveId;
}

[DataMemberattribute]

public AVAArchiveDate parmArchiveDate(AVAArchiveDate _archiveDate = archiveDate)
{
    archiveDate = _archiveDate;
    return archiveDate;
}

public boolean validate()
{
    boolean isValid = true;

    if (!archiveDate)
    {
        isValid = checkFailed("@NDX:NXAArchiveDateMissing");
    }
    if (!archiveId)
    {
        isValid = checkFailed("@NDX:NXAArchiveIDMissing");
    }


    return isValid;
}
